function serializeColumns(columns) {
  if (columns === null || typeof columns !== "object") {
    throw new TypeError("columns must be a plain object");
  }

  var prototype = Object.getPrototypeOf(columns);
  if (prototype !== Object.prototype && prototype !== null) {
    throw new TypeError("columns must be a plain object");
  }

  var keys = columns.keys;
  var values = columns.values;

  if (!Array.isArray(keys) || !Array.isArray(values) || keys.length !== values.length) {
    throw new TypeError("keys and values must be equally sized arrays");
  }

  var pairs = [];

  for (var i = 0; i < keys.length; i++) {
    if (!Object.prototype.hasOwnProperty.call(keys, i) ||
        !Object.prototype.hasOwnProperty.call(values, i)) {
      throw new TypeError("keys and values must be dense arrays");
    }

    var key = keys[i];
    var value = values[i];

    if (typeof key !== "string" ||
        (value !== null && typeof value !== "string")) {
      throw new TypeError("invalid key or value");
    }

    pairs.push({
      name: encodeRFC3986(key),
      value: encodeRFC3986(value === null ? "" : value)
    });
  }

  pairs.sort(function (a, b) {
    if (a.name < b.name) return -1;
    if (a.name > b.name) return 1;
    if (a.value < b.value) return -1;
    if (a.value > b.value) return 1;
    return 0;
  });

  var result = [];
  for (var j = 0; j < pairs.length; j++) {
    result.push(pairs[j].name + "=" + pairs[j].value);
  }
  return result.join("&");
}

function encodeRFC3986(value) {
  var hex = "0123456789ABCDEF";
  var result = "";

  for (var i = 0; i < value.length; i++) {
    var code = value.charCodeAt(i);

    if (code >= 0xD800 && code <= 0xDBFF) {
      if (i + 1 >= value.length) {
        throw new URIError("Unpaired surrogate");
      }

      var low = value.charCodeAt(++i);
      if (low < 0xDC00 || low > 0xDFFF) {
        throw new URIError("Unpaired surrogate");
      }

      code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
    } else if (code >= 0xDC00 && code <= 0xDFFF) {
      throw new URIError("Unpaired surrogate");
    }

    if (
      code >= 0x41 && code <= 0x5A ||
      code >= 0x61 && code <= 0x7A ||
      code >= 0x30 && code <= 0x39 ||
      code === 0x2D || code === 0x2E ||
      code === 0x5F || code === 0x7E
    ) {
      result += String.fromCharCode(code);
    } else if (code <= 0x7F) {
      result += "%" + hex[(code >> 4) & 0xF] + hex[code & 0xF];
    } else if (code <= 0x7FF) {
      result += percentByte(0xC0 | (code >> 6), hex);
      result += percentByte(0x80 | (code & 0x3F), hex);
    } else if (code <= 0xFFFF) {
      result += percentByte(0xE0 | (code >> 12), hex);
      result += percentByte(0x80 | ((code >> 6) & 0x3F), hex);
      result += percentByte(0x80 | (code & 0x3F), hex);
    } else {
      result += percentByte(0xF0 | (code >> 18), hex);
      result += percentByte(0x80 | ((code >> 12) & 0x3F), hex);
      result += percentByte(0x80 | ((code >> 6) & 0x3F), hex);
      result += percentByte(0x80 | (code & 0x3F), hex);
    }
  }

  return result;
}

function percentByte(byte, hex) {
  return "%" + hex[(byte >> 4) & 0xF] + hex[byte & 0xF];
}
